--
-- Table structure for table `biaya_proyek`
--

CREATE TABLE `biaya_proyek` (
  `id` int UNSIGNED NOT NULL,
  `id_proyek` int UNSIGNED NOT NULL COMMENT 'Relasi ke proyek(id)',
  `id_pengumpulan_proyek` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke pengumpulan_proyek(id) jika sudah ada laporan akhir',
  `id_proyek_kelompok` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke proyek_kelompok(id) jika proyek kelompok',
  `id_siswa` int UNSIGNED NOT NULL COMMENT 'Relasi ke siswa(id) / id_mahasiswa pencatat / bendahara pengeluaran',
  `id_kelas_mata_pelajaran` int UNSIGNED NOT NULL COMMENT 'Relasi ke kelas_mata_pelajaran(id) / id_kelas_matkul',
  `tanggal_pengeluaran` date NOT NULL COMMENT 'Tanggal transaksi biaya dikeluarkan (YYYY-MM-DD)',
  `kategori_biaya` enum('Bahan Baku & Alat','Percetakan & Jilid','Transportasi','Konsumsi','Persewaan Perangkat','Digital / Cloud / Lisensi','Lain-lain') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Bahan Baku & Alat' COMMENT 'Pos anggaran pengeluaran',
  `nama_item_biaya` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Nama barang / jasa (contoh: Kertas Manila & Cat Poster, Sewa Kamera 1 Hari)',
  `kuantitas` decimal(8,2) NOT NULL DEFAULT '1.00' COMMENT 'Jumlah kuantitas item',
  `satuan` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'pcs' COMMENT 'Satuan kuantitas (pcs, paket, unit, rim, hari, lembar)',
  `harga_satuan` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Harga satuan dalam Rupiah',
  `total_biaya` decimal(12,2) NOT NULL DEFAULT '0.00' COMMENT 'Total nominal biaya (kuantitas x harga_satuan)',
  `bukti_transaksi` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'File foto struk / nota / kwitansi belanja (jpg/png/pdf)',
  `sumber_dana` enum('Iuran Mandiri Siswa','BOS / Sekolah','Sponsor / Donatur','Kas Kelas') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Iuran Mandiri Siswa' COMMENT 'Asal sumber pendanaan biaya',
  `status_verifikasi` enum('Menunggu Verifikasi','Diverifikasi Guru','Ditolak') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Diverifikasi Guru' COMMENT 'Status verifikasi transparansi pengeluaran oleh guru',
  `catatan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Catatan keterangan tambahan penggunaan anggaran',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `cbt_jawaban_siswa`
--

CREATE TABLE `cbt_jawaban_siswa` (
  `id` int UNSIGNED NOT NULL,
  `id_sesi_ujian` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke cbt_sesi_ujian(id)',
  `tipe_asesmen` enum('diagnostik','formatif','sumatif','remedial') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'sumatif',
  `id_asesmen` int UNSIGNED NOT NULL COMMENT 'Relasi ke id asesmen terkait',
  `id_soal` int UNSIGNED NOT NULL COMMENT 'Relasi ke id butir soal terkait',
  `id_siswa` int UNSIGNED NOT NULL COMMENT 'Relasi ke siswa(id)',
  `nomor_urut_tampil` int NOT NULL DEFAULT '1' COMMENT 'Nomor urut soal yang tampil di layar siswa',
  `tipe_soal` enum('Pilihan Ganda','Pilihan Ganda Kompleks','Essay / Uraian','Benar Salah','Menjodohkan','Tugas Terbimbing','Studi Kasus Khusus') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Pilihan Ganda',
  `id_opsi_dipilih` int UNSIGNED DEFAULT NULL COMMENT 'ID opsi yang dipilih untuk PG tunggal',
  `kode_opsi_dipilih` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Huruf opsi yang dipilih (A, B, C, D, E)',
  `jawaban_teks` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Jawaban naratif teks untuk soal Essay / Uraian',
  `jawaban_kompleks` json DEFAULT NULL COMMENT 'Struktur JSON pilihan siswa untuk PG Kompleks, Menjodohkan, atau Benar Salah',
  `is_ragu` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Flag penanda ragu-ragu di navigasi soal (1 = Ragu-ragu, 0 = Yakin)',
  `is_benar` tinyint(1) DEFAULT NULL COMMENT 'Status koreksi otomatis: 1 = Benar, 0 = Salah, NULL = Belum Dinilai/Essay',
  `skor_bobot_maks` decimal(5,2) NOT NULL DEFAULT '10.00' COMMENT 'Bobot maksimal butir soal ini',
  `skor_diperoleh` decimal(5,2) DEFAULT NULL COMMENT 'Nilai skor yang diperoleh siswa pada butir soal ini',
  `catatan_koreksi_guru` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Catatan koreksi dari guru (khusus essay)',
  `waktu_simpan` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Waktu autosave jawaban terakhir',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `cbt_log_pelanggaran_exambro`
--

CREATE TABLE `cbt_log_pelanggaran_exambro` (
  `id` int UNSIGNED NOT NULL,
  `id_sesi_ujian` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke cbt_sesi_ujian(id)',
  `tipe_asesmen` enum('diagnostik','formatif','sumatif','remedial') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'sumatif',
  `id_asesmen` int UNSIGNED NOT NULL,
  `id_siswa` int UNSIGNED NOT NULL COMMENT 'Relasi ke siswa(id)',
  `jenis_pelanggaran` enum('Keluar Aplikasi / Home','Recent Apps / App Switcher','Split Screen / Layar Ganda','Floating Window / Aplikasi Mengambang','Tangkapan Layar / Screenshot','Perekaman Layar / Screen Recorder','Salin / Tempel Teks (Clipboard)','Kehilangan Fokus Layar','Perangkat Terdeteksi Root','Lainnya') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Keluar Aplikasi / Home',
  `keterangan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Deskripsi detail teknis kejadian',
  `sisa_waktu_detik` int DEFAULT NULL COMMENT 'Sisa waktu siswa saat pelanggaran terjadi',
  `pelanggaran_ke` int NOT NULL DEFAULT '1' COMMENT 'Urutan ke berapa pelanggaran dilakukan siswa pada sesi ini',
  `status_tindakan` enum('Peringatan','Freeze & Logout Otomatis','Terkunci Permanen') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Freeze & Logout Otomatis',
  `ip_address` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_agent` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `waktu_kejadian` datetime DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `cbt_pengaturan_exambro`
--

CREATE TABLE `cbt_pengaturan_exambro` (
  `id` int UNSIGNED NOT NULL,
  `kode_pengaturan` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'default_kiosk',
  `nama_pengaturan` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Standar Keamanan Ilmuna Exam Browser',
  `wajib_exambro` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1 = Siswa wajib mengerjakan via APK Exam Browser resmi, blokir browser biasa',
  `blokir_screenshot` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1 = Aktifkan FLAG_SECURE anti screenshot/record',
  `blokir_copy_paste` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1 = Nonaktifkan copy, cut, paste, dan text selection',
  `auto_freeze_on_leave` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1 = Otomatis freeze sisa waktu saat keluar aplikasi',
  `auto_logout_on_leave` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1 = Otomatis logout sesi aplikasi saat keluar aplikasi',
  `butuh_buka_manual_admin` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1 = Siswa yang ter-freeze tidak bisa login sendiri, harus dibuka manual oleh admin di dashboard',
  `maks_toleransi_pelanggaran` int NOT NULL DEFAULT '3' COMMENT 'Batas toleransi pelanggaran sebelum diskualifikasi/kunci permanen (0 = langsung kunci)',
  `pin_pengawas_kiosk` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '123456' COMMENT 'PIN darurat pengawas untuk keluar mode kiosk',
  `keterangan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `cbt_sesi_ujian`
--

CREATE TABLE `cbt_sesi_ujian` (
  `id` int UNSIGNED NOT NULL,
  `tipe_asesmen` enum('diagnostik','formatif','sumatif','remedial') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'sumatif',
  `id_asesmen` int UNSIGNED NOT NULL COMMENT 'Relasi dinamis ke asesmen_diagnostik, asesmen_formatif, atau asesmen_sumatif',
  `id_siswa` int UNSIGNED NOT NULL COMMENT 'Relasi ke siswa(id)',
  `id_kelas_mata_pelajaran` int UNSIGNED NOT NULL COMMENT 'Relasi ke kelas_mata_pelajaran(id)',
  `nomor_peserta` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Nomor peserta ujian jika menggunakan tiket khusus',
  `token_sesi` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Token ujian dinamis yang dimasukkan siswa',
  `status_sesi` enum('Belum Mulai','Sedang Mengerjakan','Terkunci / Freeze','Selesai','Izin Keluar','Dibuka Ulang') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Sedang Mengerjakan',
  `sisa_waktu_detik` int NOT NULL DEFAULT '0' COMMENT 'Sisa durasi pengerjaan yang dibekukan',
  `waktu_mulai` datetime DEFAULT CURRENT_TIMESTAMP COMMENT 'Waktu siswa pertama kali memulai pengerjaan',
  `waktu_selesai` datetime DEFAULT NULL COMMENT 'Waktu siswa menyelesaikan ujian secara resmi',
  `is_frozen` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 = Sesi dibekukan karena keluar aplikasi/pelanggaran',
  `waktu_freeze` datetime DEFAULT NULL COMMENT 'Waktu terjadinya pembekuan sesi',
  `alasan_freeze` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Penyebab freeze: Keluar Aplikasi / Home, Recent Apps, Split Screen, dll',
  `total_pelanggaran` int NOT NULL DEFAULT '0' COMMENT 'Jumlah akumulasi pelanggaran siswa selama ujian',
  `is_locked_admin` tinyint(1) NOT NULL DEFAULT '0' COMMENT '1 = Memerlukan buka kunci manual oleh admin/proktor agar bisa login lagi',
  `dibuka_oleh` int DEFAULT NULL COMMENT 'Relasi ke users(id) admin/guru yang membuka kunci',
  `waktu_buka_kunci` datetime DEFAULT NULL COMMENT 'Waktu pembukaan kunci oleh admin',
  `catatan_proktor` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Catatan admin saat verifikasi atau pembukaan kunci',
  `susunan_soal_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Daftar ID butir soal teracak per siswa agar susunan soal tetap sama saat dilanjutkan',
  `device_model` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Merk dan tipe perangkat siswa',
  `ip_address` varchar(45) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'IP Address siswa saat mengerjakan',
  `user_agent` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'User Agent khusus Exam Browser',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

