  `nss` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Nomor Statistik Sekolah',
  `nds` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Nomor Data Sekolah',
  `jenjang` enum('SD','MI','SMP','MTs','SMA','MA','SMK','MAK','PKBM','Perguruan Tinggi','Lainnya') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'SMA',
  `status_sekolah` enum('Negeri','Swasta') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Swasta',
  `akreditasi` enum('A','B','C','Belum Terakreditasi') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'A',
  `kurikulum_utama` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Kurikulum Merdeka',
  `sk_pendirian` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Nomor SK Pendirian Sekolah',
