--
-- Table structure for table `itp`
--

CREATE TABLE `itp` (
  `id` int UNSIGNED NOT NULL,
  `id_tp` int UNSIGNED NOT NULL COMMENT 'Relasi beruntut ke tujuan pembelajaran (tp)',
  `id_atp` int UNSIGNED DEFAULT NULL COMMENT 'Relasi opsional ke alur tujuan pembelajaran (atp)',
  `kode_itp` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Kode Indikator (misal: 1.1.1, 1.1.2)',
  `itp` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Teks Indikator Tujuan Pembelajaran (ITP / IKTP)',
  `deskripsi_ketercapaian` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Kriteria / rubrik ketercapaian kompetensi',
  `urutan` int DEFAULT '1' COMMENT 'Nomor urut indikator',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

