--
-- Table structure for table `jadwal_pelajaran`
--

CREATE TABLE `jadwal_pelajaran` (
  `id` int UNSIGNED NOT NULL,
  `id_kelas_mata_pelajaran` int UNSIGNED NOT NULL COMMENT 'Relasi ke kelas_mata_pelajaran',
  `id_guru` int DEFAULT NULL COMMENT 'Relasi ke users(id) guru pengampu',
  `id_modul_ajar` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke modul_ajar(id) pertemuan ini',
  `id_cp` int UNSIGNED DEFAULT NULL,
  `id_tp` int UNSIGNED DEFAULT NULL,
  `id_hari_efektif` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke kalender hari_efektif(id)',
  `id_pekan_efektif` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke rincian pekan_efektif(id)',
  `id_titik_sekolah` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke titik_koordinat_sekolah(id) acuan lokasi KBM',
  `pertemuan_ke` int NOT NULL DEFAULT '1' COMMENT 'Nomor urut pertemuan KBM (1, 2, 3...)',
  `tahun_pelajaran` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '2026/2027',
  `semester` enum('Ganjil','Genap') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Ganjil',
  `hari` enum('Senin','Selasa','Rabu','Kamis','Jumat','Sabtu','Minggu') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Senin',
  `tanggal` date NOT NULL COMMENT 'Tanggal KBM terlaksana (YYYY-MM-DD)',
  `jam_mulai` time NOT NULL DEFAULT '07:00:00' COMMENT 'Jam mulai KBM',
  `jam_selesai` time NOT NULL DEFAULT '08:30:00' COMMENT 'Jam berakhir KBM',
  `alokasi_jp` int NOT NULL DEFAULT '2' COMMENT 'Alokasi Jam Pelajaran (JP)',
  `jam_ke` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT '1-2',
  `materi_pembahasan` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Judul / pokok materi pembahasan pertemuan ini',
  `jenis_agenda` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Materi KBM',
  `ruangan` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'Ruang Kelas PAI' COMMENT 'Lokasi / ruangan KBM berlangsung',
  `status_jadwal` enum('Terjadwal','Berlangsung','Selesai','Dibatalkan','Diganti') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Terjadwal',
  `status_pelaksanaan` enum('Belum Terlaksana','Terlaksana','Tidak Terlaksana','Ditunda') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Belum Terlaksana',
  `catatan_pelaksanaan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `keterangan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Catatan agenda / instruksi guru',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

