  `id_mata_pelajaran` int UNSIGNED NOT NULL,
  `id_guru_mata_pelajaran` bigint UNSIGNED DEFAULT NULL,
  `kode_kelas_mapel` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
