--
-- Table structure for table `lkpd`
--

CREATE TABLE `lkpd` (
  `id` int UNSIGNED NOT NULL,
  `id_kelas_mata_pelajaran` int UNSIGNED NOT NULL COMMENT 'Relasi ke kelas_mata_pelajaran(id) / id_kelas_matkul',
  `id_guru` int DEFAULT NULL COMMENT 'Relasi ke users(id) guru penyusun',
  `id_modul_ajar` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke modul_ajar(id) pertemuan terkait',
  `id_cp` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke cp(id)',
  `id_tp` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke tp(id)',
  `id_atp` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke atp(id)',
  `id_itp` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke itp(id)',
  `pertemuan_ke` int NOT NULL DEFAULT '1' COMMENT 'Pertemuan ke berapa KBM',
  `nomor_lkpd` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'LKPD-01' COMMENT 'Nomor identifikasi LKPD',
  `judul_lkpd` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Judul LKPD (contoh: LKPD 01: Eksplorasi Fenomena Alam dan Karakteristik Ulil Albab)',
  `tujuan_aktivitas` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Tujuan aktivitas belajar yang dicapai melalui LKPD',
  `petunjuk_kerja` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Petunjuk langkah-langkah kerja siswa (individu/kelompok)',
  `alokasi_waktu_menit` int NOT NULL DEFAULT '45' COMMENT 'Alokasi durasi waktu pengerjaan',
  `file_lampiran` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'File panduan LKPD PDF/Docx jika ada',
  `status` enum('Draft','Aktif','Ditutup') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Aktif',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `lkpd_soal`
--

CREATE TABLE `lkpd_soal` (
  `id` int UNSIGNED NOT NULL,
  `id_lkpd` int UNSIGNED NOT NULL COMMENT 'Relasi ke master lkpd(id)',
  `id_kelas_mata_pelajaran` int UNSIGNED NOT NULL COMMENT 'Relasi ke kelas_mata_pelajaran(id) / id_kelas_matkul',
  `id_modul_ajar` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke modul_ajar(id)',
  `pertemuan_ke` int NOT NULL DEFAULT '1' COMMENT 'Pertemuan ke berapa KBM',
  `id_cp` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke cp(id)',
  `id_tp` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke tp(id)',
  `id_atp` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke atp(id)',
  `id_itp` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke itp(id)',
  `nomor_soal` int NOT NULL DEFAULT '1' COMMENT 'Nomor urut butir soal (1, 2, 3...)',
  `tipe_soal` enum('Pilihan Ganda','Pilihan Ganda Kompleks','Essay / Uraian','Lembar Aktivitas Siswa','Eksperimen / Prosedural') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Lembar Aktivitas Siswa' COMMENT 'Tipe format lembar aktivitas',
  `pertanyaan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Teks stimulus, instruksi lembar aktivitas, atau butir pertanyaan',
  `gambar_stimulus` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Gambar ilustrasi/grafik/tabel aktivitas',
  `tingkat_kesulitan` enum('Mudah','Sedang','Sukar') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Sedang',
  `level_kognitif` enum('C1 - Mengingat','C2 - Memahami','C3 - Mengaplikasikan','C4 - Menganalisis','C5 - Mengevaluasi','C6 - Mencipta') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'C3 - Mengaplikasikan',
  `bobot_skor` decimal(5,2) NOT NULL DEFAULT '10.00' COMMENT 'Bobot skor maksimal butir lembar kerja ini',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `lkpd_soal_opsi`
--

CREATE TABLE `lkpd_soal_opsi` (
  `id` int UNSIGNED NOT NULL,
  `id_soal` int UNSIGNED NOT NULL COMMENT 'Relasi ke lkpd_soal(id)',
  `kode_opsi` enum('A','B','C','D','E') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Pilihan opsi jawaban (A s.d E)',
  `teks_opsi` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Narasi teks pilihan jawaban',
  `gambar_opsi` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Gambar ilustrasi opsi jika ada',
  `is_kunci_jawaban` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Kunci jawaban benar (1 = Benar, 0 = Pengecoh)',
  `penjelasan_kunci` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Pembahasan ilmiah kunci jawaban',
  `bobot_nilai_opsi` decimal(5,2) DEFAULT NULL COMMENT 'Nilai skor jika opsi ini dipilih'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `lkpd_soal_rubrik`
--

CREATE TABLE `lkpd_soal_rubrik` (
  `id` int UNSIGNED NOT NULL,
  `id_soal` int UNSIGNED NOT NULL COMMENT 'Relasi unik 1 soal 1 rubrik ke lkpd_soal(id)',
  `id_itp` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke itp(id) indikator tujuan pembelajaran yang diukur',
  `aspek_kompetensi` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Aspek keterampilan/kerja ilmiah yang dinilai',
  `pedoman_penskoran` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Panduan teknis bagi guru dalam memberikan skor',
  `skor_maksimal` decimal(5,2) NOT NULL DEFAULT '10.00' COMMENT 'Skor batas tertinggi untuk aktivitas ini',
  `kriteria_skor_maksimal` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Deskriptor capaian bila siswa memperoleh skor maksimal',
  `kriteria_skor_sedang` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Deskriptor capaian bila siswa memperoleh skor sedang/sebagian',
  `kriteria_skor_minimal` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Deskriptor capaian bila siswa memperoleh skor dasar/minimal',
  `kriteria_skor_nol` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Deskriptor capaian bila siswa memperoleh skor 0 (salah total/kosong)',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `mapel`
--

CREATE TABLE `mapel` (
  `id` bigint UNSIGNED NOT NULL,
