--
-- Table structure for table `modul_ajar`
--

CREATE TABLE `modul_ajar` (
  `id` int UNSIGNED NOT NULL,
  `id_kelas_mata_pelajaran` int UNSIGNED NOT NULL COMMENT 'Relasi ke kelas_mata_pelajaran',
  `id_cp` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke Capaian Pembelajaran',
  `id_tp` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke Tujuan Pembelajaran',
  `id_atp` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke Alur Tujuan Pembelajaran',
  `id_itp` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke Indikator Tujuan Pembelajaran (ITP / IKTP)',
  `id_model_pembelajaran` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke Model Pembelajaran',
  `id_metode_pembelajaran` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke Metode Pembelajaran Utama',
  `id_materi` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke bank materi yang dipilih untuk pertemuan ini',
  `id_guru` int DEFAULT NULL COMMENT 'Relasi ke users(id) guru penyusun',
  `pertemuan_ke` int NOT NULL DEFAULT '1' COMMENT 'Pertemuan ke berapa (1, 2, 3...)',
  `judul_modul` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Judul modul ajar / materi pokok',
  `fase` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Fase E' COMMENT 'Fase A/B/C/D/E/F Kurikulum Merdeka',
  `alokasi_waktu` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '2 x 45 Menit' COMMENT 'Alokasi jam pelajaran',
  `profil_pelajar_pancasila` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Dimensi Profil Pelajar Pancasila & Rahmatan Lil Alamin',
  `sarana_prasarana` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Media, alat peraga, dan lingkungan belajar',
  `target_peserta_didik` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'Peserta Didik Reguler / Tipikal',
  `pemahaman_bermakna` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Nilai esensial dan kemanfaatan materi di dunia nyata',
  `pertanyaan_pemantik` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Pertanyaan pemantik nalar kritis',
  `kegiatan_pendahuluan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Apersepsi, salam, motivasi, dan penyampaian tujuan',
  `kegiatan_inti` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Langkah inti pembelajaran selaras sintaks model terpilih',
  `kegiatan_penutup` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Rangkuman, refleksi, asesmen singkat, dan doa',
  `asesmen_diagnostik` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Asesmen awal kesiapan belajar',
  `asesmen_formatif` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Asesmen proses (rubrik observasi, LKPD, unjuk kerja)',
  `asesmen_sumatif` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Asesmen ketercapaian kompetensi akhir',
  `pengayaan_remedial` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Program tindak lanjut murid mahir dan murid yang tertinggal',
  `refleksi_guru_siswa` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Evaluasi keterlaksanaan KBM pendidik dan refleksi siswa',
  `lkpd` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Panduan Lembar Kerja Peserta Didik',
  `bahan_bacaan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Ringkasan materi literasi guru dan murid',
  `glosarium` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Daftar istilah penting',
  `daftar_pustaka` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Sumber rujukan referensi buku / artikel',
  `file_lampiran` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'File upload dokumen modul (pdf/docx)',
  `status` enum('Draft','Published','Archived') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Published',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

