) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `nilai_pengayaan_remedial`
--

CREATE TABLE `nilai_pengayaan_remedial` (
  `id` int UNSIGNED NOT NULL,
  `id_siswa` int UNSIGNED NOT NULL COMMENT 'Relasi ke siswa(id) / id_mahasiswa yang dinilai',
  `id_kelas_mata_pelajaran` int UNSIGNED NOT NULL COMMENT 'Relasi ke kelas_mata_pelajaran(id) / id_kelas_matkul',
  `id_pengayaan_remedial` int UNSIGNED NOT NULL COMMENT 'Relasi ke master pengayaan_remedial(id)',
  `id_guru` int DEFAULT NULL COMMENT 'Relasi ke users(id) guru penilai',
  `id_modul_ajar` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke modul_ajar(id)',
  `id_tp` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke tp(id)',
  `id_itp` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke itp(id)',
  `pertemuan_ke` int NOT NULL DEFAULT '1' COMMENT 'Pertemuan ke berapa KBM',
  `nilai_awal` decimal(5,2) DEFAULT NULL COMMENT 'Nilai awal sebelum remedial/pengayaan',
  `nilai_akhir` decimal(5,2) NOT NULL COMMENT 'Nilai akhir setelah program tindak lanjut',
  `nilai_kktp` decimal(5,2) NOT NULL DEFAULT '75.00' COMMENT 'Kriteria Ketercapaian batas tuntas',
  `predikat` enum('A','B','C','D','E') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Konversi predikat huruf',
  `status_tuntas` enum('Tuntas Remedial','Belum Tuntas','Pengayaan Berhasil') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Tuntas Remedial' COMMENT 'Status ketercapaian tindak lanjut',
  `catatan_evaluasi` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Catatan evaluasi guru & hasil perkembangan siswa',
  `waktu_penilaian` datetime DEFAULT CURRENT_TIMESTAMP COMMENT 'Waktu penilaian dicatat',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `nilai_tugas`
--

CREATE TABLE `nilai_tugas` (
  `id` int UNSIGNED NOT NULL,
  `id_tugas` int UNSIGNED NOT NULL COMMENT 'Relasi ke tugas(id)',
  `id_pengumpulan_tugas` int UNSIGNED NOT NULL COMMENT 'Relasi ke pengumpulan_tugas(id) yang dinilai',
  `id_siswa` int UNSIGNED NOT NULL COMMENT 'Relasi ke siswa(id) / id_mahasiswa yang dinilai',
  `id_kelas_mata_pelajaran` int UNSIGNED NOT NULL COMMENT 'Relasi ke kelas_mata_pelajaran(id) / id_kelas_matkul',
  `id_guru` int DEFAULT NULL COMMENT 'Relasi ke users(id) guru penilai',
  `nilai` decimal(5,2) NOT NULL COMMENT 'Skor angka nilai tugas (contoh: 88.50 dari 100.00)',
  `nilai_kelompok` decimal(5,2) DEFAULT NULL,
  `nilai_bagi_kelompok` decimal(5,2) DEFAULT NULL,
  `nilai_individu` decimal(5,2) DEFAULT NULL,
  `jumlah_anggota_kelompok` int DEFAULT NULL,
  `nilai_remedial` decimal(5,2) DEFAULT NULL,
  `nilai_akhir_remedial` decimal(5,2) DEFAULT NULL,
  `status_remedial` varchar(35) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `catatan_remedial` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `predikat` enum('A','B','C','D','E') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Konversi huruf mutu (A: Sangat Baik, B: Baik, C: Cukup, D: Kurang, E: Sangat Kurang)',
  `aspek_itp_ketercapaian` enum('Tercapai Sangat Baik','Tercapai','Cukup Tercapai','Perlu Bimbingan') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Tercapai' COMMENT 'Evaluasi ketercapaian Indikator Tujuan Pembelajaran (ITP/IKTP)',
  `catatan_guru` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Catatan evaluasi, umpan balik (feedback) dan saran perbaikan dari guru',
  `status_penilaian` enum('Dinilai','Perlu Revisi','Tuntas') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Dinilai' COMMENT 'Status hasil penilaian tugas',
  `waktu_penilaian` datetime DEFAULT CURRENT_TIMESTAMP COMMENT 'Waktu guru memberikan nilai',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `pekan_efektif`
--

CREATE TABLE `pekan_efektif` (
  `id` int UNSIGNED NOT NULL,
  `id_kelas_mata_pelajaran` int UNSIGNED NOT NULL COMMENT 'Relasi ke kelas_mata_pelajaran',
  `tahun_pelajaran` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '2026/2027' COMMENT 'Tahun ajaran aktif',
  `semester` enum('Ganjil','Genap') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Ganjil' COMMENT 'Semester pembelajaran',
  `bulan` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Nama bulan kalender akademik',
  `urutan_bulan` int NOT NULL COMMENT 'Urutan bulan akademik (1: Juli s.d 12: Juni)',
  `senin` int NOT NULL DEFAULT '0' COMMENT 'Jumlah hari Senin efektif di bulan ini',
  `selasa` int NOT NULL DEFAULT '0' COMMENT 'Jumlah hari Selasa efektif di bulan ini',
  `rabu` int NOT NULL DEFAULT '0' COMMENT 'Jumlah hari Rabu efektif di bulan ini',
  `kamis` int NOT NULL DEFAULT '0' COMMENT 'Jumlah hari Kamis efektif di bulan ini',
  `jumat` int NOT NULL DEFAULT '0' COMMENT 'Jumlah hari Jumat efektif di bulan ini',
  `sabtu` int NOT NULL DEFAULT '0' COMMENT 'Jumlah hari Sabtu efektif di bulan ini',
  `minggu` int NOT NULL DEFAULT '0' COMMENT 'Jumlah hari Minggu efektif di bulan ini',
  `total_hari_efektif` int NOT NULL DEFAULT '0' COMMENT 'Total hari efektif bulan ini (Sum Senin s.d Minggu)',
  `jumlah_pekan_total` int NOT NULL DEFAULT '4' COMMENT 'Total jumlah pekan dalam bulan (Jml Pekan di Excel)',
  `jumlah_pekan_efektif` int NOT NULL DEFAULT '4' COMMENT 'Jumlah pekan efektif KBM (Pekan Efektif di Excel)',
  `jumlah_pekan_tidak_efektif` int NOT NULL DEFAULT '0' COMMENT 'Jumlah pekan non-KBM',
  `keterangan_tidak_efektif` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Rincian agenda non-efektif (MPLS, asesmen, libur)',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `pengayaan_remedial`
--

CREATE TABLE `pengayaan_remedial` (
  `id` int UNSIGNED NOT NULL,
  `id_kelas_mata_pelajaran` int UNSIGNED NOT NULL COMMENT 'Relasi ke kelas_mata_pelajaran(id) / id_kelas_matkul',
  `id_guru` int DEFAULT NULL COMMENT 'Relasi ke users(id) guru pengampu',
  `id_modul_ajar` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke modul_ajar(id)',
  `id_cp` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke cp(id)',
  `id_tp` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke tp(id)',
  `id_atp` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke atp(id)',
  `id_itp` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke itp(id)',
  `pertemuan_ke` int NOT NULL DEFAULT '1' COMMENT 'Pertemuan ke berapa KBM',
  `kategori` enum('Pengayaan','Remedial') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Remedial' COMMENT 'Program tindak lanjut hasil asesmen',
  `judul_program` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Judul program pengayaan / remedial',
  `kktp_minimal` decimal(5,2) NOT NULL DEFAULT '75.00' COMMENT 'Standar kriteria ketuntasan acuan',
  `bentuk_kegiatan` enum('Bimbingan Perorangan','Tutor Sebaya','Penugasan Khusus Terbimbing','Pembelajaran Ulang Materi Tertentu','Proyek Mini Pendalaman') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Bimbingan Perorangan' COMMENT 'Metode pelaksanaan',
  `petunjuk_pelaksanaan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Instruksi dan alur pelaksanaan program',
  `durasi_menit` int NOT NULL DEFAULT '60' COMMENT 'Durasi pengerjaan CBT (menit)',
  `tanggal_pelaksanaan` date DEFAULT NULL,
  `jam_mulai` time DEFAULT NULL,
  `jam_selesai` time DEFAULT NULL,
  `status` enum('Draft','Aktif','Selesai','Ditutup') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Aktif',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

