  `id_soal` int UNSIGNED NOT NULL COMMENT 'Relasi ke pengayaan_remedial_soal(id)',
  `kode_opsi` enum('A','B','C','D','E') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Pilihan opsi jawaban (A s.d E)',
  `teks_opsi` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Narasi teks pilihan jawaban',
  `gambar_opsi` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Gambar ilustrasi opsi jika ada',
  `is_kunci_jawaban` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Kunci jawaban benar (1 = Benar, 0 = Pengecoh)',
  `penjelasan_kunci` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Pembahasan ilmiah kunci jawaban',
  `bobot_nilai_opsi` decimal(5,2) DEFAULT NULL COMMENT 'Nilai skor jika opsi ini dipilih'
