--
-- Table structure for table `pengumpulan_proyek`
--

CREATE TABLE `pengumpulan_proyek` (
  `id` int UNSIGNED NOT NULL,
  `id_proyek` int UNSIGNED NOT NULL COMMENT 'Relasi ke proyek(id)',
  `id_siswa` int UNSIGNED NOT NULL COMMENT 'Relasi ke siswa(id) / id_mahasiswa pengumpul/ketua',
  `id_kelas_mata_pelajaran` int UNSIGNED NOT NULL COMMENT 'Relasi ke kelas_mata_pelajaran(id) / id_kelas_matkul',
  `id_proyek_kelompok` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke proyek_kelompok(id) jika pengerjaan kelompok',
  `judul_laporan_produk` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Judul hasil karya / laporan akhir proyek',
  `deskripsi_produk` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Deskripsi inovasi produk, manfaat, dan hasil pengerjaan',
  `file_laporan` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Path berkas laporan ilmiah / booklet PDF',
  `file_dokumentasi` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Path arsip dokumentasi proses kegiatan (ZIP/PDF)',
  `link_produk` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Tautan hasil karya digital (Google Drive, Youtube, GitHub, Canva, Figma, Web Hosting)',
  `link_video_presentasi` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Tautan video presentasi / pameran gelar karya',
  `waktu_pengumpulan` datetime DEFAULT CURRENT_TIMESTAMP COMMENT 'Waktu penyerahan hasil karya',
  `status_pengumpulan` enum('Diserahkan','Revisi','Disetujui','Dipublikasikan') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Diserahkan',
  `nilai_proyek` decimal(5,2) DEFAULT NULL COMMENT 'Skor angka hasil penilaian guru',
  `predikat_proyek` enum('Sangat Berkembang (SB)','Berkembang Sesuai Harapan (BSH)','Mulai Berkembang (MB)','Belum Berkembang (BB)') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Predikat P5 / Capaian Proyek',
  `catatan_evaluasi_guru` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Umpan balik dan catatan apresiasi dari guru',
  `waktu_penilaian` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

