--
-- Table structure for table `pengumpulan_tugas`
--

CREATE TABLE `pengumpulan_tugas` (
  `id` int UNSIGNED NOT NULL,
  `id_tugas` int UNSIGNED NOT NULL COMMENT 'Relasi ke tugas(id)',
  `id_siswa` int UNSIGNED NOT NULL COMMENT 'Relasi ke siswa(id) / id_mahasiswa yang mengumpulkan',
  `id_kelas_mata_pelajaran` int UNSIGNED NOT NULL COMMENT 'Relasi ke kelas_mata_pelajaran(id) / id_kelas_matkul',
  `id_tugas_kelompok` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke tugas_kelompok(id) jika tugas kelompok',
  `tipe_pengumpulan` enum('File Upload','Link URL','File dan Link','Teks / Essay') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'File Upload' COMMENT 'Metode pengumpulan yang digunakan siswa',
  `file_tugas` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Path berkas tugas yang diunggah (PDF/Docx/Zip)',
  `file_nama_asli` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Nama berkas original saat diunggah',
  `file_ukuran_kb` int DEFAULT NULL COMMENT 'Ukuran file dalam kilobyte (KB)',
  `link_tugas` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Tautan link URL pengumpulan (Google Drive, Docs, Figma, Video, dll)',
  `gdrive_file_id` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gdrive_view_url` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `gdrive_preview_url` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `gdrive_folder_path` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `catatan_siswa` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Catatan/keterangan pengerjaan atau jawaban teks essay siswa',
  `waktu_pengumpulan` datetime DEFAULT CURRENT_TIMESTAMP COMMENT 'Waktu siswa mengirimkan tugas',
  `status_pengumpulan` enum('Diserahkan','Terlambat','Draft','Menunggu Revisi') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Diserahkan' COMMENT 'Status penyerahan tugas',
  `is_terlambat` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Flag 1 jika dikumpulkan setelah tenggat_waktu tugas',
  `revisi_ke` int NOT NULL DEFAULT '1' COMMENT 'Nomor versi pengumpulan jika ada revisi',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `perizinan`
--

CREATE TABLE `perizinan` (
  `id` int UNSIGNED NOT NULL,
  `id_siswa` int UNSIGNED NOT NULL COMMENT 'Relasi ke siswa(id) pemohon izin',
  `id_kelas_mata_pelajaran` int UNSIGNED NOT NULL COMMENT 'Relasi ke kelas_mata_pelajaran',
  `id_jadwal` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke jadwal_pelajaran(id)',
  `id_modul_ajar` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke modul_ajar(id)',
  `pertemuan_ke` int NOT NULL DEFAULT '1' COMMENT 'Pertemuan ke berapa yang dimohonkan izin',
  `tanggal_izin` date NOT NULL COMMENT 'Tanggal izin berlaku (YYYY-MM-DD)',
  `jenis_izin` enum('Izin','Sakit') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Izin' COMMENT 'Kategori perizinan: Izin (I) atau Sakit (S)',
  `alasan` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Uraian lengkap alasan perizinan',
  `bukti_perizinan` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'File upload dokumen / bukti izin (surat dokter/surat ortu: pdf/jpg/png)',
  `latitude` decimal(10,8) DEFAULT NULL COMMENT 'Latitude posisi siswa saat mengajukan izin',
  `longitude` decimal(11,8) DEFAULT NULL COMMENT 'Longitude posisi siswa saat mengajukan izin',
  `alamat_izin` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Nama tempat / alamat fisik saat izin diajukan',
  `approval_ketua_kelas` enum('Pending','Approved','Rejected') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Pending' COMMENT 'Tahap 1: Wajib di-approve ketua kelas terlebih dahulu',
  `id_ketua_kelas` int DEFAULT NULL COMMENT 'Relasi ke users(id) akun ketua kelas yang memverifikasi',
  `waktu_approval_ketua` datetime DEFAULT NULL COMMENT 'Waktu ketua kelas menyetujui / menolak',
  `catatan_ketua_kelas` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Catatan / alasan reviu ketua kelas',
  `approval_guru` enum('Pending','Approved','Rejected') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Pending' COMMENT 'Tahap 2: Di-approve guru pengampu setelah ketua kelas setuju',
  `id_guru` int DEFAULT NULL COMMENT 'Relasi ke users(id) guru pengampu yang memberi keputusan akhir',
  `waktu_approval_guru` datetime DEFAULT NULL COMMENT 'Waktu guru menyetujui / menolak',
  `catatan_guru` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Catatan / pesan dari guru',
  `status_perizinan` enum('Menunggu Persetujuan Ketua Kelas','Menunggu Persetujuan Guru','Disetujui','Ditolak') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Menunggu Persetujuan Ketua Kelas' COMMENT 'Status akumulatif alur persetujuan',
