CREATE TABLE `titik_koordinat_sekolah` (
  `id` int UNSIGNED NOT NULL,
  `nama_lokasi` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Nama titik/gedung (contoh: Kampus Utama, Gedung KBM PAI Lantai 2)',
  `latitude` decimal(10,8) NOT NULL COMMENT 'Titik koordinat latitude GPS',
  `longitude` decimal(11,8) NOT NULL COMMENT 'Titik koordinat longitude GPS',
  `radius_meter` int NOT NULL DEFAULT '50' COMMENT 'Radius toleransi kehadiran dalam meter untuk geofencing',
  `alamat` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT 'Alamat fisik / deskripsi lokasi',
  `is_active` tinyint(1) NOT NULL DEFAULT '1' COMMENT 'Status aktif titik koordinat (1=Aktif, 0=Nonaktif)',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `tp`
--

CREATE TABLE `tp` (
  `id` int UNSIGNED NOT NULL,
  `id_cp` int UNSIGNED NOT NULL,
  `kode_tp` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Kode/Nomor TP (misal: 1.1, 2.1-2.3)',
  `tp` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Teks Tujuan Pembelajaran (TP)',
  `materi_pokok` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Materi pokok terkait TP (misal: Berpikir Kritis dalam Islam)',
  `alokasi_jam` int DEFAULT '4' COMMENT 'Alokasi default jam pelajaran (JP)',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

--
-- Table structure for table `tugas`
--

CREATE TABLE `tugas` (
  `id` int UNSIGNED NOT NULL,
  `id_kelas_mata_pelajaran` int UNSIGNED NOT NULL COMMENT 'Relasi ke kelas_mata_pelajaran(id) / id_kelas_matkul',
  `id_guru` int DEFAULT NULL COMMENT 'Relasi ke users(id) guru pembuat tugas',
  `id_modul_ajar` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke modul_ajar(id) pertemuan terkait',
  `id_tp` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke tp(id) tujuan pembelajaran',
  `id_itp` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke itp(id) indikator tujuan pembelajaran',
  `id_jadwal` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke jadwal_pelajaran(id) pertemuan KBM',
  `pertemuan_ke` int NOT NULL DEFAULT '1' COMMENT 'Pertemuan ke berapa KBM',
  `judul_tugas` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Judul / nama penugasan',
  `deskripsi_instruksi` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Instruksi detail teknis pengerjaan tugas & rubrik asesmen',
  `jenis_penugasan` enum('Individu','Kelompok') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Individu' COMMENT 'Kategori penugasan: Individu atau Kelompok',
  `tipe_pengumpulan` enum('File Upload','Link URL','File atau Link','Teks / Essay') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'File atau Link' COMMENT 'Metode pengumpulan tugas yang diizinkan',
  `format_file_diizinkan` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'pdf,docx,zip' COMMENT 'Ekstensi berkas yang diizinkan (misal: pdf, docx, zip)',
  `file_lampiran_tugas` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'File lampiran LKPD / panduan soal dari guru (PDF/Docx)',
  `link_sumber_tugas` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Link referensi materi / video / literatur penunjang tugas',
  `gdrive_file_id` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `gdrive_view_url` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `gdrive_preview_url` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `nilai_maksimal` decimal(5,2) NOT NULL DEFAULT '100.00' COMMENT 'Skor maksimal tugas (default 100.00)',
  `bobot_nilai` int NOT NULL DEFAULT '10' COMMENT 'Bobot persentase nilai terhadap nilai akhir',
  `tanggal_mulai` datetime DEFAULT CURRENT_TIMESTAMP COMMENT 'Waktu tugas mulai dapat diakses siswa',
  `tenggat_waktu` datetime NOT NULL COMMENT 'Batas akhir (deadline) waktu pengumpulan tugas',
  `status_tugas` enum('Draft','Dibuka','Ditutup') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Dibuka' COMMENT 'Status ketersediaan tugas',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- --------------------------------------------------------

