  `nama_kelompok` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Nama kelompok (contoh: Kelompok 1 - Abu Bakar Ash-Shiddiq)',
  `id_ketua_kelompok` int UNSIGNED DEFAULT NULL COMMENT 'Relasi ke siswa(id) koordinator/ketua kelompok',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

