--
-- Structure for view `announcements`
--
DROP TABLE IF EXISTS `announcements`;

CREATE OR REPLACE VIEW `announcements`  AS SELECT 1 AS `id`, 'Selamat Datang di Ilmuna Learn Kurikulum Merdeka' AS `title`, 'Sistem Pembelajaran Digital Terintegrasi 69 Tabel PDP & SIAKAD.' AS `content`, 1 AS `class_id`, 'all' AS `target_role`, 1 AS `author_id`, 1 AS `is_pinned`, now() AS `created_at` ;

-- --------------------------------------------------------

--
-- Structure for view `assignments`
--
DROP TABLE IF EXISTS `assignments`;

CREATE OR REPLACE VIEW `assignments`  AS SELECT `t`.`id` AS `id`, `t`.`judul_tugas` AS `title`, `t`.`jenis_penugasan` AS `category`, `kmp`.`id_kelas` AS `class_id`, `t`.`id_guru` AS `author_id`, `t`.`deskripsi_instruksi` AS `description`, `t`.`tenggat_waktu` AS `due_date`, `t`.`nilai_maksimal` AS `max_score`, `t`.`status_tugas` AS `status`, `t`.`created_at` AS `created_at` FROM (`tugas` `t` left join `kelas_mata_pelajaran` `kmp` on((`t`.`id_kelas_mata_pelajaran` = `kmp`.`id`))) ;

-- --------------------------------------------------------

--
-- Structure for view `attendances`
--
DROP TABLE IF EXISTS `attendances`;

CREATE OR REPLACE VIEW `attendances`  AS SELECT coalesce(`a`.`id`,1) AS `id`, coalesce(`kmp`.`id_kelas`,1) AS `class_id`, 1 AS `recorded_by`, coalesce(cast(`a`.`waktu_absen` as date),curdate()) AS `attendance_date`, concat('Pertemuan ke-',`a`.`pertemuan_ke`) AS `meeting_topic`, coalesce(`a`.`keterangan`,'Presensi Digital Siswa') AS `notes`, coalesce(`a`.`waktu_absen`,now()) AS `created_at` FROM (`absensi` `a` left join `kelas_mata_pelajaran` `kmp` on((`a`.`id_kelas_mata_pelajaran` = `kmp`.`id`))) ;

-- --------------------------------------------------------

--
-- Structure for view `attendance_details`
--
DROP TABLE IF EXISTS `attendance_details`;

CREATE OR REPLACE VIEW `attendance_details`  AS SELECT `a`.`id` AS `id`, `a`.`id` AS `attendance_id`, `a`.`id_siswa` AS `student_id`, (case when (`a`.`status` = 'H') then 'hadir' when (`a`.`status` = 'I') then 'izin' when (`a`.`status` = 'S') then 'sakit' else 'alpa' end) AS `status`, `a`.`keterangan` AS `notes`, `a`.`waktu_absen` AS `marked_at` FROM `absensi` AS `a` ;

-- --------------------------------------------------------

--
-- Structure for view `classes`
--
DROP TABLE IF EXISTS `classes`;

CREATE OR REPLACE VIEW `classes`  AS SELECT `kelas`.`id` AS `id`, `kelas`.`nama_kelas` AS `name`, (case when ((`kelas`.`nama_kelas` like 'X-%') or (`kelas`.`nama_kelas` like 'X %')) then 'X' when ((`kelas`.`nama_kelas` like 'XI-%') or (`kelas`.`nama_kelas` like 'XI %')) then 'XI' when ((`kelas`.`nama_kelas` like 'XII-%') or (`kelas`.`nama_kelas` like 'XII %')) then 'XII' else 'X' end) AS `grade_level`, `kelas`.`tahun_pelajaran` AS `academic_year`, NULL AS `ketua_kelas_id`, `kelas`.`created_at` AS `created_at` FROM `kelas` ;

-- --------------------------------------------------------

--
-- Structure for view `class_members`
--
DROP TABLE IF EXISTS `class_members`;

CREATE OR REPLACE VIEW `class_members`  AS SELECT `s`.`id` AS `id`, `s`.`id_kelas` AS `class_id`, `s`.`id` AS `user_id`, `s`.`created_at` AS `joined_at` FROM `siswa` AS `s` ;

-- --------------------------------------------------------

--
-- Structure for view `kelas_mapel`
--
DROP TABLE IF EXISTS `kelas_mapel`;

