--
-- Structure for view `v_absensi_asesmen_sumatif`
--
DROP TABLE IF EXISTS `v_absensi_asesmen_sumatif`;

CREATE OR REPLACE VIEW `v_absensi_asesmen_sumatif`  AS SELECT `aasum`.`id` AS `id`, `aasum`.`id_asesmen_sumatif` AS `id_asesmen_sumatif`, `asum`.`judul_asesmen` AS `judul_asesmen`, `asum`.`jenis_sumatif` AS `jenis_sumatif`, `asum`.`durasi_menit` AS `durasi_menit`, `asum`.`tanggal_pelaksanaan` AS `tanggal_pelaksanaan`, `aasum`.`nomor_peserta` AS `nomor_peserta`, `aasum`.`id_siswa` AS `id_siswa`, `s`.`nisn` AS `nisn`, `s`.`nis` AS `nis`, `s`.`nama_lengkap` AS `nama_siswa`, `s`.`foto` AS `foto_siswa`, `s`.`id_kelas` AS `id_kelas`, `k`.`nama_kelas` AS `nama_kelas`, `aasum`.`id_kelas_mata_pelajaran` AS `id_kelas_mata_pelajaran`, `mp`.`nama_mata_pelajaran` AS `nama_mata_pelajaran`, `aasum`.`status_kehadiran` AS `status_kehadiran`, `aasum`.`metode_absen` AS `metode_absen`, `aasum`.`waktu_absen` AS `waktu_absen`, `aasum`.`diabsen_oleh` AS `diabsen_oleh`, `u`.`full_name` AS `nama_petugas`, `aasum`.`keterangan` AS `keterangan`, `aasum`.`created_at` AS `created_at` FROM ((((((`absensi_asesmen_sumatif` `aasum` join `asesmen_sumatif` `asum` on((`aasum`.`id_asesmen_sumatif` = `asum`.`id`))) join `siswa` `s` on((`aasum`.`id_siswa` = `s`.`id`))) left join `kelas` `k` on((`s`.`id_kelas` = `k`.`id`))) join `kelas_mata_pelajaran` `kmp` on((`aasum`.`id_kelas_mata_pelajaran` = `kmp`.`id`))) left join `mata_pelajaran` `mp` on((`kmp`.`id_mata_pelajaran` = `mp`.`id`))) left join `users` `u` on((`aasum`.`diabsen_oleh` = `u`.`id`))) ;

