--
-- Structure for view `v_kelayakan_remedial`
--
DROP TABLE IF EXISTS `v_kelayakan_remedial`;

CREATE OR REPLACE VIEW `v_kelayakan_remedial`  AS SELECT `s`.`id` AS `id_siswa`, `kmp`.`id` AS `id_kelas_mata_pelajaran`, coalesce(`ns`.`pertemuan_ke`,`nf`.`pertemuan_ke`,`nd`.`pertemuan_ke`,`npr`.`pertemuan_ke`,1) AS `pertemuan_ke`, `nd`.`id` AS `id_nilai_diagnostik`, `nf`.`id` AS `id_nilai_formatif`, `ns`.`id` AS `id_nilai_sumatif`, coalesce(`nd`.`nilai_angka`,0.00) AS `nilai_diagnostik`, coalesce(`nf`.`nilai_angka`,0.00) AS `nilai_formatif`, coalesce(`ns`.`nilai_angka`,`npr`.`nilai_awal`,0.00) AS `nilai_sumatif`, coalesce(`ns`.`nilai_kktp`,`nf`.`nilai_kktp`,`nd`.`nilai_kktp`,`npr`.`nilai_kktp`,75.00) AS `kktp_acuan` FROM (((((`siswa` `s` join `kelas_mata_pelajaran` `kmp` on((`kmp`.`id_kelas` = `s`.`id_kelas`))) left join `nilai_asesmen_diagnostik` `nd` on(((`nd`.`id_siswa` = `s`.`id`) and (`nd`.`id_kelas_mata_pelajaran` = `kmp`.`id`)))) left join `nilai_asesmen_formatif` `nf` on(((`nf`.`id_siswa` = `s`.`id`) and (`nf`.`id_kelas_mata_pelajaran` = `kmp`.`id`)))) left join `nilai_asesmen_sumatif` `ns` on(((`ns`.`id_siswa` = `s`.`id`) and (`ns`.`id_kelas_mata_pelajaran` = `kmp`.`id`)))) left join `nilai_pengayaan_remedial` `npr` on(((`npr`.`id_siswa` = `s`.`id`) and (`npr`.`id_kelas_mata_pelajaran` = `kmp`.`id`)))) WHERE (((`nd`.`id` is not null) AND (`nd`.`nilai_angka` < coalesce(nullif(`nd`.`nilai_kktp`,0),75.00))) OR ((`nf`.`id` is not null) AND (`nf`.`nilai_angka` < coalesce(nullif(`nf`.`nilai_kktp`,0),75.00))) OR ((`ns`.`id` is not null) AND (`ns`.`nilai_angka` < coalesce(nullif(`ns`.`nilai_kktp`,0),75.00))) OR ((`npr`.`id` is not null) AND (`npr`.`nilai_awal` < coalesce(nullif(`npr`.`nilai_kktp`,0),75.00)))) ;

-- --------------------------------------------------------

--
-- Structure for view `v_monitoring_absensi_sumatif`
--
DROP TABLE IF EXISTS `v_monitoring_absensi_sumatif`;

CREATE OR REPLACE VIEW `v_monitoring_absensi_sumatif`  AS SELECT `aas`.`id` AS `id_akses`, `aas`.`id_asesmen_sumatif` AS `id_asesmen_sumatif`, `asum`.`judul_asesmen` AS `judul_asesmen`, `asum`.`jenis_sumatif` AS `jenis_sumatif`, `asum`.`tanggal_pelaksanaan` AS `tanggal_pelaksanaan`, `asum`.`durasi_menit` AS `durasi_menit`, `aas`.`id_kelas_mata_pelajaran` AS `id_kelas_mata_pelajaran`, `k`.`id` AS `id_kelas`, `k`.`nama_kelas` AS `nama_kelas`, `mp`.`id` AS `id_mata_pelajaran`, `mp`.`nama_mata_pelajaran` AS `nama_mata_pelajaran`, `aas`.`id_siswa` AS `id_siswa`, `s`.`nisn` AS `nisn`, `s`.`nis` AS `nis`, `s`.`nama_lengkap` AS `nama_siswa`, `s`.`foto` AS `foto_siswa`, `aas`.`nomor_peserta` AS `nomor_peserta`, `aas`.`username_ujian` AS `username_ujian`, `aas`.`token_sesi` AS `token_sesi`, `aas`.`status_akses` AS `status_cbt`, `aasum`.`id` AS `id_absensi`, coalesce(`aasum`.`status_kehadiran`,'Belum Hadir') AS `status_kehadiran`, `aasum`.`metode_absen` AS `metode_absen`, `aasum`.`waktu_absen` AS `waktu_absen`, `aasum`.`diabsen_oleh` AS `diabsen_oleh`, `u`.`full_name` AS `nama_petugas`, `aasum`.`keterangan` AS `keterangan`, (case when (`aasum`.`id` is not null) then 1 else 0 end) AS `is_sudah_absen` FROM (((((((`akses_asesmen_sumatif` `aas` join `asesmen_sumatif` `asum` on((`aas`.`id_asesmen_sumatif` = `asum`.`id`))) join `siswa` `s` on((`aas`.`id_siswa` = `s`.`id`))) left join `kelas` `k` on((`s`.`id_kelas` = `k`.`id`))) join `kelas_mata_pelajaran` `kmp` on((`aas`.`id_kelas_mata_pelajaran` = `kmp`.`id`))) left join `mata_pelajaran` `mp` on((`kmp`.`id_mata_pelajaran` = `mp`.`id`))) left join `absensi_asesmen_sumatif` `aasum` on(((`aasum`.`id_asesmen_sumatif` = `aas`.`id_asesmen_sumatif`) and (`aasum`.`id_siswa` = `aas`.`id_siswa`)))) left join `users` `u` on((`aasum`.`diabsen_oleh` = `u`.`id`))) ;

