INSERT INTO `asesmen_diagnostik_soal_rubrik` (`id`, `id_soal`, `id_itp`, `aspek_kompetensi`, `pedoman_penskoran`, `skor_maksimal`, `kriteria_skor_maksimal`, `kriteria_skor_sedang`, `kriteria_skor_minimal`, `kriteria_skor_nol`, `created_at`, `updated_at`) VALUES
(2, 7, 1, 'Pemahaman Konsep & Refleksi Penerapan Zikir', 'Jawaban memuat minimal 3 poin utama: 1) Mendekatkan diri kepada Allah SWT (taqarrub ilallah), 2) Menjauhkan hati dari kegelisahan, stres, dan prasangka buruk (QS Ar-Ra\'d: 28), 3) Menjaga lisan dari perkataan sia-sia dan menguatkan akhlak terpuji.', 20.00, 'Menjelaskan minimal 3 hikmah dan keutamaan zikir secara komprehensif, runtut, menghubungkan dengan dalil/konsep ketenteraman jiwa secara tepat dan mendalam (Skor 20).', 'Menjelaskan 2 hikmah zikir dengan benar dan cukup jelas, namun uraian hubungan dengan ketenteraman jiwa masih bersifat umum (Skor 14).', 'Hanya menyebutkan 1 hikmah zikir secara singkat tanpa penjelasan atau terdapat kekeliruan konsep minor (Skor 8).', 'Jawaban tidak relevan dengan pertanyaan atau tidak memberikan jawaban sama sekali (Skor 0).', '2026-10-23 13:14:05', '2026-10-23 13:14:05'),
(3, 8, 1, 'Analisis Sikap Toleransi & Batasan Akidah', 'Penerapan tasamuh yang benar mencakup: menghormati perbedaan suku/agama dalam muamalah dan kemanusiaan, tolong-menolong dalam kebaikan umum, tidak memaksakan keyakinan (QS Al-Kafirun: 6 & QS Al-Baqarah: 256), serta tidak mengikuti ritual ibadah agama lain.', 20.00, 'Mampu menguraikan prinsip tasamuh secara tepat, memberikan contoh konkrit di sekolah, dan menjelaskan batasan akidah-ibadah dengan argumen yang jelas dan shahih (Skor 20).', 'Menjelaskan sikap tasamuh dan memberikan contoh pergaulan, namun batasan akidah dan ibadah belum dijelaskan secara mendalam (Skor 14).', 'Hanya memberikan contoh pergaulan umum tanpa mengaitkan dengan prinsip syariat Islam (Skor 8).', 'Tidak menjawab atau jawaban bertentangan dengan ajaran Islam (Skor 0).', '2026-10-23 13:14:05', '2026-10-23 13:14:05');
INSERT INTO `asesmen_formatif` (`id`, `id_kelas_mata_pelajaran`, `id_guru`, `id_modul_ajar`, `id_cp`, `id_tp`, `id_atp`, `id_itp`, `pertemuan_ke`, `judul_asesmen`, `teknik_asesmen`, `tujuan_asesmen`, `petunjuk_pengerjaan`, `tanggal_pelaksanaan`, `jam_mulai`, `jam_selesai`, `durasi_menit`, `status`, `created_at`, `updated_at`) VALUES
(1, 7, 2, 1, 1, 1, 1, 2, 2, 'Asesmen Formatif Proses KBM: Kuis Analisis Karakteristik Ulil Albab', 'Tes Tertulis', 'Mengukur pemahaman proses murid terkait kriteria ulil albab dan memberikan feedback perbaikan.', 'Kerjakan kuis pemahaman konsep berikut pada lembar kerja digital dalam waktu 20 menit.', '2026-10-21', '07:30:00', '09:00:00', 60, 'Ditutup', '2026-10-18 21:45:20', '2026-10-28 15:44:01');
INSERT INTO `asesmen_formatif_soal` (`id`, `id_asesmen_formatif`, `id_kelas_mata_pelajaran`, `id_modul_ajar`, `pertemuan_ke`, `id_cp`, `id_tp`, `id_atp`, `id_itp`, `nomor_soal`, `tipe_soal`, `pertanyaan`, `gambar_stimulus`, `link_video`, `tingkat_kesulitan`, `level_kognitif`, `bobot_skor`, `created_at`, `updated_at`) VALUES
(1, 1, 7, 1, 2, 1, 1, 1, 2, 1, 'Essay / Uraian', 'Sebutkan 3 dampak destruktif dari penyebaran berita hoaks bagi keharmonisan ukhuwah islamiyah dan bagaimana solusinya menurut perspektif Islam!', NULL, NULL, 'Sedang', 'C3 - Mengaplikasikan', 15.00, '2026-10-18 21:45:20', '2026-10-18 21:45:20');
INSERT INTO `asesmen_formatif_soal_rubrik` (`id`, `id_soal`, `id_itp`, `aspek_kompetensi`, `pedoman_penskoran`, `skor_maksimal`, `kriteria_skor_maksimal`, `kriteria_skor_sedang`, `kriteria_skor_minimal`, `kriteria_skor_nol`, `created_at`, `updated_at`) VALUES
(1, 1, 2, 'Aplikasi Nilai Preventif Hoaks dalam Kehidupan Remaja', 'Penilaian rubrik holistik: 3 dampak konkret (6 poin), solusi tabayyun & etika (9 poin).', 15.00, 'Menyebutkan 3 dampak hoaks secara tepat dan merumuskan solusi tabayyun islami yang terukur (Skor 13-15).', 'Menyebutkan dampak tetapi solusi kurang spesifik (Skor 8-12).', 'Hanya menyebutkan 1 dampak secara umum (Skor 3-7).', 'Tidak menjawab atau jawaban tidak relevan (Skor 0).', '2026-10-18 21:45:20', '2026-10-18 21:45:20');
