(1, 1, 1, 'Makharijul Huruf (Tempat Keluar Huruf)', 'Pengucapan huruf hijaiyah dari makhraj yang tepat tanpa tertukar (tenggorokan, lidah, bibir).', 30.00, 4, '4=Sangat Fasih, 3=Fasih, 2=Cukup Fasih, 1=Kurang Fasih', '2026-11-02 09:50:53', '2026-11-02 09:50:53'),
(2, 1, 2, 'Ketepatan Hukum Tajwid (Ghunnah, Mad, Idgham)', 'Penerapan panjang pendek mad 2-6 harakat dan dengung ghunnah secara tepat.', 35.00, 4, '4=Sangat Tepat Sesuai Kaidah, 3=Tepat, 2=Ada 1-2 Kesalahan, 1=Banyak Kesalahan', '2026-11-02 09:50:53', '2026-11-02 09:50:53'),
(3, 1, 3, 'Kelancaran & Ketukan Ketukan Irama', 'Kelancaran melafalkan ayat tanpa terbata-bata dengan jeda waqaf/ibtida yang benar.', 20.00, 4, '4=Sangat Lancar, 3=Lancar, 2=Kurang Lancar, 1=Terbata-bata', '2026-11-02 09:50:53', '2026-11-02 09:50:53'),
(4, 1, 4, 'Adab & Sikap Unjuk Kerja', 'Sikap duduk tegak tawadhu, membaca ta\'awwudz dan basmalah dengan khusyuk.', 15.00, 4, '4=Sangat Khusyuk & Santun, 3=Baik, 2=Cukup, 1=Kurang', '2026-11-02 09:50:53', '2026-11-02 09:50:53'),
(5, 2, 1, 'Makharijul Huruf (Tempat Keluar Huruf)', 'Pengucapan huruf hijaiyah dari makhraj yang tepat tanpa tertukar (tenggorokan, lidah, bibir).', 30.00, 4, '4=Sangat Fasih, 3=Fasih, 2=Cukup Fasih, 1=Kurang Fasih', '2026-11-02 09:51:53', '2026-11-02 09:51:53'),
(6, 2, 2, 'Ketepatan Hukum Tajwid (Ghunnah, Mad, Idgham)', 'Penerapan panjang pendek mad 2-6 harakat dan dengung ghunnah secara tepat.', 35.00, 4, '4=Sangat Tepat Sesuai Kaidah, 3=Tepat, 2=Ada 1-2 Kesalahan, 1=Banyak Kesalahan', '2026-11-02 09:51:53', '2026-11-02 09:51:53'),
(7, 2, 3, 'Kelancaran & Ketukan Ketukan Irama', 'Kelancaran melafalkan ayat tanpa terbata-bata dengan jeda waqaf/ibtida yang benar.', 20.00, 4, '4=Sangat Lancar, 3=Lancar, 2=Kurang Lancar, 1=Terbata-bata', '2026-11-02 09:51:53', '2026-11-02 09:51:53'),
(8, 2, 4, 'Adab & Sikap Unjuk Kerja', 'Sikap duduk tegak tawadhu, membaca ta\'awwudz dan basmalah dengan khusyuk.', 15.00, 4, '4=Sangat Khusyuk & Santun, 3=Baik, 2=Cukup, 1=Kurang', '2026-11-02 09:51:53', '2026-11-02 09:51:53');
