INSERT INTO `asesmen_sumatif_soal` (`id`, `id_asesmen_sumatif`, `id_kelas_mata_pelajaran`, `id_modul_ajar`, `pertemuan_ke`, `id_cp`, `id_tp`, `id_atp`, `id_itp`, `nomor_soal`, `tipe_soal`, `pertanyaan`, `gambar_stimulus`, `link_video`, `tingkat_kesulitan`, `level_kognitif`, `bobot_skor`, `created_at`, `updated_at`) VALUES
(17, 13, 2, 2, 1, 2, 3, 5, 6, 1, 'Pilihan Ganda', 'Perhatikan gambar stimulus terkait rukun Islam di atas! Manakah di antara pernyataan berikut yang merupakan rukun Islam yang pertama dan menjadi pondasi keimanan seorang muslim?', 'uploads/stimulus/stimulus_1792644325_3e69ad57.png', NULL, 'Sedang', 'C3 - Mengaplikasikan', 10.00, '2026-10-22 11:45:38', '2026-10-22 11:45:38'),
(18, 13, 2, 2, 1, 2, 3, 5, 6, 2, 'Pilihan Ganda', 'Simaklah tayangan video pembelajaran mengenai keagungan Al-Qur\'an pada tautan video YouTube berikut! Berdasarkan tayangan video tersebut, Surah Al-Fatihah dijuluki sebagai Ummul Kitab karena...\n[Gambar Stimulus: Silakan Paste / Sisipkan Gambar langsung di sini jika butir soal ini memerlukan gambar stimulus visual]', NULL, 'https://www.youtube.com/watch?v=0e3GPea1Tyg', 'Sedang', 'C3 - Mengaplikasikan', 10.00, '2026-10-22 11:45:38', '2026-10-22 11:45:38'),
(19, 13, 2, 2, 1, 2, 3, 5, 6, 3, 'Pilihan Ganda', 'Sikap toleransi dan saling menghormati perbedaan keyakinan dalam ajaran Islam diistilahkan dengan...\n[Gambar Stimulus: Silakan Paste / Sisipkan Gambar langsung di sini jika butir soal ini memerlukan gambar stimulus visual]', NULL, NULL, 'Sedang', 'C3 - Mengaplikasikan', 10.00, '2026-10-22 11:45:38', '2026-10-22 11:45:38'),
(20, 13, 2, 2, 1, 2, 3, 5, 6, 4, 'Pilihan Ganda', 'Zikir secara bahasa bermakna mengingat. Tujuan utama memperbanyak zikir kepada Allah SWT adalah...\n[Gambar Stimulus: Silakan Paste / Sisipkan Gambar langsung di sini jika butir soal ini memerlukan gambar stimulus visual]', NULL, NULL, 'Sedang', 'C3 - Mengaplikasikan', 10.00, '2026-10-22 11:45:38', '2026-10-22 11:45:38'),
(21, 13, 2, 2, 1, 2, 3, 5, 6, 5, 'Pilihan Ganda', 'Salah satu adab utama ketika membaca ayat suci Al-Qur\'an adalah...\n[Gambar Stimulus: Silakan Paste / Sisipkan Gambar langsung di sini jika butir soal ini memerlukan gambar stimulus visual]', NULL, NULL, 'Sedang', 'C3 - Mengaplikasikan', 10.00, '2026-10-22 11:45:39', '2026-10-22 11:45:39'),
(22, 13, 2, 2, 1, 2, 3, 5, 6, 6, 'Essay / Uraian', 'Amati video inspirasi dan infografis stimulus zikir di atas. Jelaskan hikmah dan keutamaan mengamalkan zikir dalam kehidupan sehari-hari, serta bagaimana zikir dapat membentuk ketenteraman jiwa bagi seorang muslim!', 'uploads/stimulus/stimulus_1792644325_0048d1e4.png', 'https://www.youtube.com/watch?v=0e3GPea1Tyg', 'Sedang', 'C4 - Menganalisis', 20.00, '2026-10-22 11:45:39', '2026-10-22 11:45:39'),
(23, 13, 2, 2, 1, 2, 3, 5, 6, 7, 'Essay / Uraian', 'Bagaimanakah penerapan sikap tasamuh (toleransi) yang benar menurut syariat Islam dalam pergaulan di sekolah tanpa mencampuradukkan akidah dan ibadah? Berikan contoh konkritnya!\n[Gambar Stimulus: Silakan Paste / Sisipkan Gambar langsung di sini jika butir soal ini memerlukan gambar stimulus visual]', NULL, NULL, 'Sedang', 'C4 - Menganalisis', 20.00, '2026-10-22 11:45:39', '2026-10-22 11:45:39'),
