INSERT INTO `asesmen_sumatif_soal_rubrik` (`id`, `id_soal`, `id_itp`, `aspek_kompetensi`, `pedoman_penskoran`, `skor_maksimal`, `kriteria_skor_maksimal`, `kriteria_skor_sedang`, `kriteria_skor_minimal`, `kriteria_skor_nol`, `created_at`, `updated_at`) VALUES
(6, 22, 6, 'Pemahaman Konsep & Refleksi Penerapan Zikir', 'Jawaban memuat minimal 3 poin utama: 1) Mendekatkan diri kepada Allah SWT (taqarrub ilallah), 2) Menjauhkan hati dari kegelisahan, stres, dan prasangka buruk (QS Ar-Ra\'d: 28), 3) Menjaga lisan dari perkataan sia-sia dan menguatkan akhlak terpuji.', 20.00, 'Menjelaskan minimal 3 hikmah dan keutamaan zikir secara komprehensif, runtut, menghubungkan dengan dalil/konsep ketenteraman jiwa secara tepat dan mendalam (Skor 20).', 'Menjelaskan 2 hikmah zikir dengan benar dan cukup jelas, namun uraian hubungan dengan ketenteraman jiwa masih bersifat umum (Skor 14).', 'Hanya menyebutkan 1 hikmah zikir secara singkat tanpa penjelasan atau terdapat kekeliruan konsep minor (Skor 8).', 'Jawaban tidak relevan dengan pertanyaan atau tidak memberikan jawaban sama sekali (Skor 0).', '2026-10-22 11:45:39', '2026-10-22 11:45:39'),
(7, 23, 6, 'Analisis Sikap Toleransi & Batasan Akidah', 'Penerapan tasamuh yang benar mencakup: menghormati perbedaan suku/agama dalam muamalah dan kemanusiaan, tolong-menolong dalam kebaikan umum, tidak memaksakan keyakinan (QS Al-Kafirun: 6 & QS Al-Baqarah: 256), serta tidak mengikuti ritual ibadah agama lain.', 20.00, 'Mampu menguraikan prinsip tasamuh secara tepat, memberikan contoh konkrit di sekolah, dan menjelaskan batasan akidah-ibadah dengan argumen yang jelas dan shahih (Skor 20).', 'Menjelaskan sikap tasamuh dan memberikan contoh pergaulan, namun batasan akidah dan ibadah belum dijelaskan secara mendalam (Skor 14).', 'Hanya memberikan contoh pergaulan umum tanpa mengaitkan dengan prinsip syariat Islam (Skor 8).', 'Tidak menjawab atau jawaban bertentangan dengan ajaran Islam (Skor 0).', '2026-10-22 11:45:39', '2026-10-22 11:45:39'),
(15, 37, NULL, 'Pemahaman Konsep & Refleksi Penerapan Zikir', 'Jawaban memuat minimal 3 poin utama: 1) Mendekatkan diri kepada Allah SWT (taqarrub ilallah), 2) Menjauhkan hati dari kegelisahan, stres, dan prasangka buruk (QS Ar-Ra\'d: 28), 3) Menjaga lisan dari perkataan sia-sia dan menguatkan akhlak terpuji.', 20.00, 'Menjelaskan minimal 3 hikmah dan keutamaan zikir secara komprehensif, runtut, menghubungkan dengan dalil/konsep ketenteraman jiwa secara tepat dan mendalam (Skor 20).', 'Menjelaskan 2 hikmah zikir dengan benar dan cukup jelas, namun uraian hubungan dengan ketenteraman jiwa masih bersifat umum (Skor 14).', 'Hanya menyebutkan 1 hikmah zikir secara singkat tanpa penjelasan atau terdapat kekeliruan konsep minor (Skor 8).', 'Jawaban tidak relevan dengan pertanyaan atau tidak memberikan jawaban sama sekali (Skor 0).', '2026-10-29 16:01:03', '2026-10-29 16:01:03'),
(16, 38, NULL, 'Analisis Sikap Toleransi & Batasan Akidah', 'Penerapan tasamuh yang benar mencakup: menghormati perbedaan suku/agama dalam muamalah dan kemanusiaan, tolong-menolong dalam kebaikan umum, tidak memaksakan keyakinan (QS Al-Kafirun: 6 & QS Al-Baqarah: 256), serta tidak mengikuti ritual ibadah agama lain.', 20.00, 'Mampu menguraikan prinsip tasamuh secara tepat, memberikan contoh konkrit di sekolah, dan menjelaskan batasan akidah-ibadah dengan argumen yang jelas dan shahih (Skor 20).', 'Menjelaskan sikap tasamuh dan memberikan contoh pergaulan, namun batasan akidah dan ibadah belum dijelaskan secara mendalam (Skor 14).', 'Hanya memberikan contoh pergaulan umum tanpa mengaitkan dengan prinsip syariat Islam (Skor 8).', 'Tidak menjawab atau jawaban bertentangan dengan ajaran Islam (Skor 0).', '2026-10-29 16:01:03', '2026-10-29 16:01:03');
INSERT INTO `atp` (`id`, `id_tp`, `atp`, `urutan`, `created_at`) VALUES
(1, 1, '11.1 Membaca QS. Ali Imran: 190-191 dan hadis terkait berpikir kritis dengan tartil.', 1, '2026-10-18 21:45:19'),
(2, 1, '11.2 Menganalisis pesan dan tafsir ayat berpikir kritis dalam konteks kemajuan teknologi.', 2, '2026-10-18 21:45:19'),
(3, 2, '11.3 Menelaah 77 cabang iman (syu\'ab al-iman) dan klasifikasi 3 ranah (lisan, hati, perbuatan).', 1, '2026-10-18 21:45:19'),
(4, 3, '11.4 Mengidentifikasi dampak destruktif khamr, judi, pertikaian, dan etika bermedia sosial.', 1, '2026-10-18 21:45:19'),
(5, 4, '11.5 Membedakan syarat dan rukun khotbah Jumat, tabligh, dan dakwah serta adab penceramah.', 1, '2026-10-18 21:45:19'),
(6, 5, '11.6 Mengkaji biografi dan sumbangsih Ibnu Sina, Al-Ghazali, dan ulama dunia bagi peradaban.', 1, '2026-10-18 21:45:19'),
(7, 6, '11.7 Mengkaji dalil Al-Qur\'an tentang etos pengembangan sains dan teknologi ramah lingkungan.', 1, '2026-10-18 21:45:19'),
(8, 7, '11.8 Mensintesis integrasi pilar Iman, Islam, dan Ihsan dalam membentuk karakter insan kamil.', 1, '2026-10-18 21:45:19'),
(9, 8, '11.9 Mempraktikkan adab bertetangga, musyawarah, dan interaksi toleran dalam kebhinekaan.', 1, '2026-10-18 21:45:19'),
(10, 9, '11.10 Menganalisis transaksi jual-beli syariah, larangan riba, bai al-mudharabah, dan fintech.', 1, '2026-10-18 21:45:19'),
(11, 10, '11.11 Meneladani perjuangan Wali Songo, KH Hasyim Asy\'ari, dan KH Ahmad Dahlan di Nusantara.', 1, '2026-10-18 21:45:19');
