INSERT INTO `cp` (`id`, `id_kelas_mata_pelajaran`, `id_elemen`, `cp`, `created_at`) VALUES
(1, 7, 1, 'Memahami ayat Al-Qur’an dan hadist tentang pentingnya berpikir kritis, ilmu pengetahuan dan teknologi, memelihara kehidupan manusia, dan moderasi beragama.', '2026-10-18 21:45:19'),
(2, 7, 2, 'Memahami beberapa cabang iman (syu‘ab al īmān), keterkaitan antara iman, Islam, dan ihsan.', '2026-10-18 21:45:19'),
(3, 7, 3, 'Memahami manfaat menghindari penyakit sosial; Memahami adab bermasyarakat dan etika digital dalam Islam.', '2026-10-18 21:45:19'),
(4, 7, 4, 'Memahami ketentuan khotbah, tabligh dan dakwah, muamalah, munakahat, dan mawaris.', '2026-10-18 21:45:19'),
(5, 7, 5, 'Memahami peran tokoh ulama dalam perkembangan peradaban Islam di dunia dan peran organisasi-organisasi Islam di Indonesia.', '2026-10-18 21:45:19'),
(11, 1, 10, 'Capaian Pembelajaran Pendidikan Agama Islam & Budi Pekerti untuk Fase E', '2026-11-03 19:49:29'),
(12, 9, 11, 'Peserta didik mampu memahami beberapa cabang iman (syu‘ab al-īmān), hakikat keimanan, serta keterkaitan harmonis antara iman, Islam, dan ihsan dalam kehidupan sehari-hari.', '2026-11-03 21:31:24'),
(13, 9, 12, 'Peserta didik mampu memahami manfaat menghindari penyakit sosial; memahami adab bermasyarakat dan menerapkan etika digital dalam Islam.', '2026-11-03 21:31:24'),
(14, 2, 13, 'Peserta didik mampu memahami dan menganalisis ayat Al-Qur’an dan hadis tentang pentingnya berpikir kritis, ilmu pengetahuan dan teknologi, memelihara kehidupan manusia, dan moderasi beragama.', '2026-11-03 21:35:19');
