INSERT INTO `elemen` (`id`, `id_kelas_mata_pelajaran`, `nama_elemen`, `fase`, `deskripsi`, `created_at`, `updated_at`) VALUES
(1, 7, 'Al-Qur’an Hadis', 'Fase F', 'Elemen Al-Qur’an dan Hadis membimbing peserta didik memahami ayat suci dan hadis tentang pentingnya berpikir kritis, iptek, memelihara kehidupan, dan moderasi beragama.', '2026-10-18 21:45:19', '2026-10-18 21:45:19'),
(2, 7, 'Akidah', 'Fase F', 'Elemen Akidah membimbing peserta didik memahami cabang-cabang iman (syu‘ab al-īmān) serta keterkaitan harmonis antara iman, Islam, dan ihsan.', '2026-10-18 21:45:19', '2026-10-18 21:45:19'),
(3, 7, 'Akhlak', 'Fase F', 'Elemen Akhlak membimbing peserta didik menghindarkan diri dari berbagai penyakit sosial, membiasakan adab bermasyarakat, dan menerapkan etika digital Islami.', '2026-10-18 21:45:19', '2026-10-18 21:45:19'),
(4, 7, 'Fikih', 'Fase F', 'Elemen Fikih membimbing peserta didik memahami ketentuan khotbah, tabligh, dakwah, prinsip muamalah syariah modern, munakahat, dan mawaris.', '2026-10-18 21:45:19', '2026-10-18 21:45:19'),
(5, 7, 'Sejarah Peradaban Islam', 'Fase F', 'Elemen Sejarah Peradaban Islam membimbing peserta didik menelusuri keteladanan dan kontribusi ulama dunia dan ulama Nusantara serta peran organisasi Islam di Indonesia.', '2026-10-18 21:45:19', '2026-10-18 21:45:19'),
(10, 1, 'Fikih Ibadah', 'Fase E', 'Elemen Pendidikan Agama Islam & Budi Pekerti', '2026-11-03 19:49:29', '2026-11-03 19:49:29'),
(11, 9, 'Akidah', 'Fase E', 'Elemen Akidah membimbing peserta didik memahami cabang-cabang iman (syu‘ab al-īmān) serta keterkaitan harmonis antara iman, Islam, dan ihsan.', '2026-11-03 21:31:23', '2026-11-03 21:31:23'),
(12, 9, 'Akhlak', 'Fase E', 'Elemen Akhlak membimbing peserta didik menghindarkan diri dari berbagai penyakit sosial, membiasakan adab bermasyarakat, dan menerapkan etika digital Islami.', '2026-11-03 21:31:24', '2026-11-03 21:31:24'),
(13, 2, 'Al-Qur’an Hadis', 'Fase E', 'Elemen Al-Qur’an dan Hadis membimbing peserta didik memahami ayat suci dan hadis tentang pentingnya berpikir kritis, ilmu pengetahuan dan teknologi, memelihara kehidupan, dan moderasi beragama.', '2026-11-03 21:35:19', '2026-11-03 21:35:19');
