INSERT INTO `itp` (`id`, `id_tp`, `id_atp`, `kode_itp`, `itp`, `deskripsi_ketercapaian`, `urutan`, `created_at`, `updated_at`) VALUES
(1, 1, 1, '1.1.1', 'Membaca QS. Ali Imran: 190-191 sesuai kaidah tajwid dan makhraj secara tartil.', 'Peserta didik mampu melafalkan ayat dengan tartil tanpa kesalahan harakat maupun makhraj.', 1, '2026-10-18 21:45:19', '2026-10-18 21:45:19'),
(2, 1, 1, '1.1.2', 'Menghafal QS. Ali Imran: 190-191 dan hadis terkait berpikir kritis dengan lancar.', 'Peserta didik mampu menyetorkan hafalan tartil tanpa bantuan mushaf.', 2, '2026-10-18 21:45:19', '2026-10-18 21:45:19'),
(3, 1, 2, '1.2.1', 'Menganalisis makna dan pesan tersirat QS. Ali Imran: 190-191 tentang karakteristik ulil albab.', 'Peserta didik mampu menguraikan ciri-ciri ulil albab dan merefleksikannya dalam kemajuan zaman.', 3, '2026-10-18 21:45:19', '2026-10-18 21:45:19'),
(4, 2, 3, '2.1.1', 'Mengidentifikasi 77 cabang iman (syu‘ab al-īmān) beserta dalil naqlinya secara tepat.', 'Peserta didik mampu menyebutkan cabang iman pokok dalam lisan, hati, dan perbuatan.', 1, '2026-10-18 21:45:19', '2026-10-18 21:45:19'),
(5, 2, 3, '2.2.1', 'Mengklasifikasikan cabang iman ke dalam dimensi ma\'rifatun bil qalbi, iqrarun bil lisan, dan \'amalun bil arkan.', 'Peserta didik mampu memetakan contoh amalan ke dalam 3 ranah cabang iman.', 2, '2026-10-18 21:45:19', '2026-10-18 21:45:19'),
(6, 3, 4, '3.1.1', 'Mengidentifikasi ragam penyakit sosial (khamr, judi, pertikaian, dan hoaks) serta bahaya destruktifnya.', 'Peserta didik mampu menjelaskan dampak buruk penyakit sosial bagi individu dan masyarakat.', 1, '2026-10-18 21:45:19', '2026-10-18 21:45:19'),
(7, 3, 4, '3.2.1', 'Menganalisis dalil larangan dan merumuskan langkah preventif etika bermedia sosial.', 'Peserta didik mampu menyusun panduan etika digital islami dalam pergaulan remaja.', 2, '2026-10-18 21:45:19', '2026-10-18 21:45:19'),
(8, 4, 5, '4.1.1', 'Membedakan rukun, syarat, dan sunnah antara khotbah, tabligh, dan dakwah.', 'Peserta didik mampu menyusun matriks perbandingan rukun dan syarat secara komprehensif.', 1, '2026-10-18 21:45:19', '2026-10-18 21:45:19'),
(9, 4, 5, '4.2.1', 'Menyusun naskah khotbah/dakwah singkat bertema moderasi beragama dan toleransi.', 'Peserta didik mampu menyusun dan memperagakan ceramah ringkas dengan bahasa santun.', 2, '2026-10-18 21:45:19', '2026-10-18 21:45:19'),
(10, 5, 6, '5.1.1', 'Menelusuri biografi dan karya monumental ilmuwan muslim abad pertengahan (Ibnu Sina, Al-Ghazali).', 'Peserta didik mampu merangkum kontribusi keilmuan peradaban Islam bagi kemajuan dunia.', 1, '2026-10-18 21:45:19', '2026-10-18 21:45:19'),
(11, 6, 7, '6.1.1', 'Menganalisis dalil Al-Qur\'an tentang etos riset dan inovasi sains teknologi ramah lingkungan.', 'Peserta didik mampu mengaitkan ayat kauniyah dengan pengembangan teknologi modern.', 1, '2026-10-18 21:45:19', '2026-10-18 21:45:19'),
(12, 7, 8, '7.1.1', 'Menjelaskan integrasi pilar Iman, Islam, dan Ihsan dalam membentuk karakter insan kamil.', 'Peserta didik mampu mengilustrasikan hubungan harmonis iman, syariat, dan ihsan.', 1, '2026-10-18 21:45:19', '2026-10-18 21:45:19'),
(13, 8, 9, '8.1.1', 'Menerapkan adab bertetangga, memuliakan tamu, dan interaksi toleran antar-umat beragama.', 'Peserta didik mampu mendemonstrasikan sikap empati dan adab sosial dalam kebhinekaan.', 1, '2026-10-18 21:45:19', '2026-10-18 21:45:19'),
(14, 9, 10, '9.1.1', 'Menganalisis prinsip akad jual-beli syariah, larangan riba, bai al-mudharabah, dan fintech.', 'Peserta didik mampu menilai keabsahan akad transaksi e-commerce dan lembaga keuangan syariah.', 1, '2026-10-18 21:45:19', '2026-10-18 21:45:19'),
(15, 10, 11, '10.1.1', 'Meneladani strategi dakwah santun Wali Songo, KH Hasyim Asy\'ari, dan KH Ahmad Dahlan.', 'Peserta didik mampu mempresentasikan nilai kearifan lokal dalam dakwah Islam di Nusantara.', 1, '2026-10-18 21:45:19', '2026-10-18 21:45:19');
