INSERT INTO `pengayaan_remedial_soal_rubrik` (`id`, `id_soal`, `id_itp`, `aspek_kompetensi`, `pedoman_penskoran`, `skor_maksimal`, `kriteria_skor_maksimal`, `kriteria_skor_sedang`, `kriteria_skor_minimal`, `kriteria_skor_nol`, `created_at`, `updated_at`) VALUES
(2, 7, 6, 'Pemahaman Konsep & Refleksi Penerapan Zikir', 'Jawaban memuat minimal 3 poin utama: 1) Mendekatkan diri kepada Allah SWT (taqarrub ilallah), 2) Menjauhkan hati dari kegelisahan, stres, dan prasangka buruk (QS Ar-Ra\'d: 28), 3) Menjaga lisan dari perkataan sia-sia dan menguatkan akhlak terpuji.', 20.00, 'Menjelaskan minimal 3 hikmah dan keutamaan zikir secara komprehensif, runtut, menghubungkan dengan dalil/konsep ketenteraman jiwa secara tepat dan mendalam (Skor 20).', 'Menjelaskan 2 hikmah zikir dengan benar dan cukup jelas, namun uraian hubungan dengan ketenteraman jiwa masih bersifat umum (Skor 14).', 'Hanya menyebutkan 1 hikmah zikir secara singkat tanpa penjelasan atau terdapat kekeliruan konsep minor (Skor 8).', 'Jawaban tidak relevan dengan pertanyaan atau tidak memberikan jawaban sama sekali (Skor 0).', '2026-10-28 16:16:39', '2026-10-28 16:16:39'),
(3, 8, 6, 'Analisis Sikap Toleransi & Batasan Akidah', 'Penerapan tasamuh yang benar mencakup: menghormati perbedaan suku/agama dalam muamalah dan kemanusiaan, tolong-menolong dalam kebaikan umum, tidak memaksakan keyakinan (QS Al-Kafirun: 6 & QS Al-Baqarah: 256), serta tidak mengikuti ritual ibadah agama lain.', 20.00, 'Mampu menguraikan prinsip tasamuh secara tepat, memberikan contoh konkrit di sekolah, dan menjelaskan batasan akidah-ibadah dengan argumen yang jelas dan shahih (Skor 20).', 'Menjelaskan sikap tasamuh dan memberikan contoh pergaulan, namun batasan akidah dan ibadah belum dijelaskan secara mendalam (Skor 14).', 'Hanya memberikan contoh pergaulan umum tanpa mengaitkan dengan prinsip syariat Islam (Skor 8).', 'Tidak menjawab atau jawaban bertentangan dengan ajaran Islam (Skor 0).', '2026-10-28 16:16:39', '2026-10-28 16:16:39');
