INSERT INTO `tp` (`id`, `id_cp`, `kode_tp`, `tp`, `materi_pokok`, `alokasi_jam`, `created_at`) VALUES
(1, 1, '1.1-1.2', 'Menghafal ayat Al-Quran dan Hadis tentang pentingnya berpikir kritis. Menafsirkan ayat Al Qur’an dan Hadis tentang pentingnya berpikir kritis.', 'Berpikir Kritis dalam Islam', 4, '2026-10-18 21:45:19'),
(2, 2, '2.1-2.3', '2.1 Mempelajari Pengertian dan Dalil tentang Syu’ab al-iman. 2.2 Mengklasifikasi Pengertian dan Dalil tentang Syu’ab al-iman. 2.3 Mencontohkan Pengertian dan Dalil tentang Syu’ab al-iman.', 'Pengertian dan Dalil tentang Syu’ab al-iman.', 6, '2026-10-18 21:45:19'),
(3, 3, '3.1-3.3', '3.1 Menunjukkan beberapa penyakit sosial dalam perspektif Islam. 3.2 Menguraikan beberapa penyakit sosial dalam Perspektif Islam. 3.3 Mencontohkan beberapa penyakit sosial dalam perspektif Islam.', 'Penyakit sosial dalam perspektif Islam', 6, '2026-10-18 21:45:19'),
(4, 4, '4.1-4.3', '4.1 Menelusuri ketentuan Khotbah, Tabligh, dan Dakwah. 4.2 Menggali ketentuan Khotbah, Tabligh, dan Dakwah. 4.3 Merangkum ketentuan Khotbah, Tabligh, dan Dakwah.', 'Khotbah, Tabligh, dan Dakwah', 6, '2026-10-18 21:45:19'),
(5, 5, '5.1-5.2', '5.1 Menulis peran tokoh ulama dunia. 5.2 Menceritakan peran tokoh ulama dunia.', 'Tokoh ulama dunia', 4, '2026-10-18 21:45:19'),
(6, 1, '1.1-1.2', 'Menghafal ayat Al-Quran dan Hadis tentang Ilmu Pengetahuan dan Teknologi (IPTEK). Menafsirkan ayat Al Qur’an dan Hadis tentang Ilmu Pengetahuan dan Teknologi (IPTEK).', 'Ilmu Pengetahuan dan Teknologi (IPTEK)', 4, '2026-10-18 21:45:19'),
(7, 2, '2.1-2.3', '2.1 Mempelajari Pengertian dan Dalil tentang Keterkaitan antara Iman, Islam, dan Ihsan. 2.2 Mengklasifikasi Pengertian dan Dalil. 2.3 Mencontohkan Keterkaitan antara Iman, Islam, dan Ihsan.', 'Keterkaitan antara Iman, Islam, dan Ihsan', 6, '2026-10-18 21:45:19'),
(8, 3, '3.1-3.3', '3.1 Menunjukkan adab bermasyarakat. 3.2 Menguraikan adab bermasyarakat. 3.3 Mencontohkan adab bermasyarakat.', 'Adab bermasyarakat', 6, '2026-10-18 21:45:19'),
(9, 4, '4.1-4.3', '4.1 Menelusuri fiqh muamalah (prinsip halal-haram, akad, riba, gharar, ekonomi syariah, fintech, koperasi syariah). 4.2 Menggali fiqh muamalah. 4.3 Merangkum fiqh muamalah modern.', 'fiqh muamalah (prinsip halal-haram, akad, riba, gharar, ekonomi syariah)', 6, '2026-10-18 21:45:19'),
(10, 5, '5.1-5.2', '5.1 Menulis peran tokoh ulama Nusantara. 5.2 Menceritakan peran tokoh ulama Nusantara.', 'Tokoh ulama Nusantara', 4, '2026-10-18 21:45:19'),
(12, 11, 1.1, 'Peserta didik mampu menganalisis ketentuan pelaksanaan penyembelihan hewan qurban dan aqiqah', 'Ketentuan Qurban dan Aqiqah', 4, '2026-11-03 19:49:29'),
(13, 1, 1.12, 'Peserta didik mampu membaca ayat Al-Qur\'an (seperti Q.S. Ali ‘Imrān/3: 190–191, Q.S. ar-Rahmān/55: 33, serta ayat/hadis terkait pemeliharaan kehidupan dan moderasi beragama) dengan tartil dan fasih.', 'ayat Al-Qur’an dan hadist tentang pentingnya berpikir kritis, ilmu pengetahuan dan teknologi, memelihara kehidupan manusia, dan moderasi beragama.', 4, '2026-11-03 20:40:03'),
(14, 1, 1.13, 'Peserta didik mampu menghafalkan ayat Al-Qur’an dan Hadis pilihan beserta artinya dengan lancar.', 'ayat Al-Qur’an dan hadist tentang pentingnya berpikir kritis, ilmu pengetahuan dan teknologi, memelihara kehidupan manusia, dan moderasi beragama.', 2, '2026-11-03 20:41:10'),
(15, 1, 1.14, 'Peserta didik mampu menganalisis pesan-pesan utama dari ayat Al-Qur’an dan Hadis tentang pentingnya berpikir kritis (sebagai Ulil Albab) dan menyaring informasi secara selektif (tabayyun).', 'ayat Al-Qur’an dan hadist tentang pentingnya berpikir kritis, ilmu pengetahuan dan teknologi, memelihara kehidupan manusia, dan moderasi beragama.', 2, '2026-11-03 20:42:29'),
(16, 1, 1.15, 'Peserta didik mampu menganalisis pesan-pesan utama dari ayat Al-Qur’an dan Hadis tentang pentingnya berpikir kritis (sebagai Ulil Albab) dan menyaring informasi secara selektif (tabayyun).', 'ayat Al-Qur’an dan hadist tentang pentingnya berpikir kritis, ilmu pengetahuan dan teknologi, memelihara kehidupan manusia, dan moderasi beragama.', 40, '2026-11-03 20:46:03'),
(17, 12, 1.1, 'Mempelajari pengertian dan dalil tentang Syu’ab al-iman (cabang-cabang iman).', 'Pengertian dan Dalil Syu’ab al-iman', 4, '2026-11-03 21:31:24'),
(18, 12, 1.2, 'Mengklasifikasikan cabang-cabang iman dan keterkaitan antara iman, Islam, dan ihsan.', 'Keterkaitan Iman, Islam, dan Ihsan', 4, '2026-11-03 21:31:24'),
(19, 12, 1.3, 'Mencontohkan implementasi syu’ab al-iman dalam kehidupan pribadi dan sosial.', 'Implementasi Cabang Iman', 4, '2026-11-03 21:31:24'),
(20, 13, 2.1, 'Mengidentifikasi beberapa penyakit sosial dalam perspektif Islam dan cara menghindarinya.', 'Penyakit Sosial dalam Perspektif Islam', 4, '2026-11-03 21:31:24'),
(21, 13, 2.2, 'Menerapkan adab bermasyarakat dan etika pergaulan Islami dalam kehidupan sehari-hari.', 'Adab Bermasyarakat Islami', 4, '2026-11-03 21:31:24'),
(22, 13, 2.3, 'Menerapkan etika digital dan bijak bermedia sosial sesuai tuntunan syariat Islam.', 'Etika Digital dalam Islam', 4, '2026-11-03 21:31:24'),
(23, 14, 1.1, 'Membaca dan menghafalkan ayat Al-Qur’an dan Hadis pilihan beserta artinya dengan lancar dan tartil.', 'Tartil Membaca dan Menghafal Al-Qur’an & Hadis', 4, '2026-11-03 21:35:19'),
(24, 14, 1.2, 'Menganalisis pesan utama dari ayat Al-Qur’an dan Hadis tentang berpikir kritis dan moderasi beragama.', 'Berpikir Kritis & Moderasi Beragama', 4, '2026-11-03 21:35:19'),
(25, 14, 1.3, 'Menerapkan hukum bacaan tajwid dalam membaca ayat-ayat Al-Qur’an pilihan secara fasih.', 'Kaidah Tajwid Al-Qur’an', 4, '2026-11-03 21:35:19');
